import sys


def main():
    s = sys.stdin.readline().strip()
    n = len(s)
    best = [0] * (2 * n - 1)
    for l in range(n):
        for r in range(l, n):
            sub = s[l:r + 1]
            if sub == sub[::-1]:
                c = l + r
                if r - l + 1 > best[c]:
                    best[c] = r - l + 1
    print(sum(best))


main()
